//! OOXML preset shape geometry, evaluated from the ECMA-376 definitions as Office does.
//!
//! `data/presets.txt` is generated by `tools/build_presets.py` from `presetShapeDefinitions.xml`.
use crate::model::*;
use crate::render::Command;
use std::{
    collections::{BTreeMap, HashMap},
    f64::consts::PI,
    sync::OnceLock,
};

static TABLE: &str = include_str!("../data/presets.txt");

/// How a sub-path is filled; shading variants darken or lighten the shape's fill.
#[derive(Clone, Copy, Debug, PartialEq)]
pub(crate) enum PathFill {
    None,
    Norm,
    Lighten,
    LightenLess,
    Darken,
    DarkenLess,
}
impl PathFill {
    pub(crate) fn shade(self, c: Color) -> Color {
        let mix = |toward: f32, amount: f32| {
            let m = |v: u8| (f32::from(v) + (toward - f32::from(v)) * amount).round() as u8;
            Color(m(c.0), m(c.1), m(c.2), c.3)
        };
        match self {
            Self::Lighten => mix(255.0, 0.4),
            Self::LightenLess => mix(255.0, 0.2),
            Self::Darken => mix(0.0, 0.4),
            Self::DarkenLess => mix(0.0, 0.2),
            Self::None | Self::Norm => c,
        }
    }
}
#[derive(Clone, Debug)]
pub(crate) struct PresetPath {
    pub commands: Vec<Command>,
    pub fill: PathFill,
    pub stroke: bool,
}

/// Each preset's lines, by name.
fn table() -> &'static BTreeMap<&'static str, Vec<&'static str>> {
    static SHAPES: OnceLock<BTreeMap<&'static str, Vec<&'static str>>> = OnceLock::new();
    SHAPES.get_or_init(|| {
        let mut shapes = BTreeMap::new();
        let mut current: Option<(&str, Vec<&str>)> = None;
        for line in TABLE.lines() {
            if let Some(name) = line.strip_prefix("shape ") {
                shapes.extend(current.replace((name, Vec::new())));
            } else if let Some((_, lines)) = current.as_mut() {
                lines.push(line);
            }
        }
        shapes.extend(current);
        shapes
    })
}
pub fn exists(name: &str) -> bool {
    table().contains_key(name)
}
/// Adjust value names in order (`adj` or `adj1`, `adj2`, …).
pub fn adjust_names(name: &str) -> Vec<&'static str> {
    table()
        .get(name)
        .into_iter()
        .flatten()
        .filter_map(|l| l.strip_prefix("av "))
        .filter_map(|l| l.split_whitespace().next())
        .collect()
}
pub fn names() -> impl Iterator<Item = &'static str> {
    table().keys().copied()
}
/// Every preset with its adjust values and their defaults, for `slide-shuttle shapes`.
pub fn catalog() -> Vec<(&'static str, Vec<(&'static str, f64)>)> {
    names()
        .map(|name| {
            let adjust = table()[name]
                .iter()
                .filter_map(|l| l.strip_prefix("av "))
                .filter_map(|l| {
                    let mut words = l.split_whitespace();
                    let key = words.next()?;
                    (words.next() == Some("val")).then_some(())?;
                    Some((key, words.next()?.parse().ok()?))
                })
                .collect();
            (name, adjust)
        })
        .collect()
}
/// Open presets (lines and connectors) may carry line-end markers.
pub fn is_open(name: &str) -> bool {
    name == "line"
        || name.contains("Connector")
        || name == "arc"
        || name.ends_with("Bracket")
        || name.ends_with("Brace")
}

/// The preset's sub-paths in page units for a frame and optional adjust values.
pub(crate) fn geometry(name: &str, frame: Rect, adjust: &[f64]) -> Result<Vec<PresetPath>> {
    let lines = table()
        .get(name)
        .ok_or_else(|| invalid(format!("unknown preset shape {name}")))?;
    let (w, h) = (f64::from(frame.width), f64::from(frame.height));
    let mut vars = builtins(w, h);
    let mut given = adjust.iter();
    let mut paths = Vec::new();
    let mut path: Option<(f64, f64, PresetPath)> = None;
    let mut pen = (0.0, 0.0);
    for line in lines {
        let mut words = line.split_whitespace();
        let tag = words.next().unwrap_or("");
        let args = words.collect::<Vec<_>>();
        match tag {
            "av" => {
                let value = match given.next() {
                    Some(v) => *v,
                    None => formula(&args[1..], &vars)?,
                };
                vars.insert(args[0].into(), value);
            }
            "gd" => {
                let value = formula(&args[1..], &vars)?;
                vars.insert(args[0].into(), value);
            }
            "path" => {
                paths.extend(path.take().map(|p| p.2));
                let num = |s: &str| s.parse::<f64>().unwrap_or(0.0);
                path = Some((
                    num(args[0]),
                    num(args[1]),
                    PresetPath {
                        commands: Vec::new(),
                        fill: match args[2] {
                            "none" => PathFill::None,
                            "lighten" => PathFill::Lighten,
                            "lightenLess" => PathFill::LightenLess,
                            "darken" => PathFill::Darken,
                            "darkenLess" => PathFill::DarkenLess,
                            _ => PathFill::Norm,
                        },
                        stroke: args[3] != "false",
                    },
                ));
            }
            _ => {
                let Some((pw, ph, current)) = path.as_mut() else {
                    return Err(invalid(format!("preset {name} draws outside a path")));
                };
                // A path with its own size is scaled to the frame, guides included.
                let (sx, sy) = (
                    if *pw > 0.0 { w / *pw } else { 1.0 },
                    if *ph > 0.0 { h / *ph } else { 1.0 },
                );
                let value = |s: &str| operand(s, &vars);
                let point = |i: usize| -> Result<(f64, f64)> {
                    Ok((value(args[2 * i])? * sx, value(args[2 * i + 1])? * sy))
                };
                let at = |(x, y): (f64, f64)| (frame.x + x as f32, frame.y + y as f32);
                match tag {
                    "M" => {
                        pen = point(0)?;
                        let (x, y) = at(pen);
                        current.commands.push(Command::M(x, y));
                    }
                    "L" => {
                        pen = point(0)?;
                        let (x, y) = at(pen);
                        current.commands.push(Command::L(x, y));
                    }
                    "Q" => {
                        let (c, end) = (point(0)?, point(1)?);
                        // Elevate the quadratic to a cubic.
                        let c1 = (
                            pen.0 + 2.0 / 3.0 * (c.0 - pen.0),
                            pen.1 + 2.0 / 3.0 * (c.1 - pen.1),
                        );
                        let c2 = (
                            end.0 + 2.0 / 3.0 * (c.0 - end.0),
                            end.1 + 2.0 / 3.0 * (c.1 - end.1),
                        );
                        let ((a, b), (c, d), (e, f)) = (at(c1), at(c2), at(end));
                        current.commands.push(Command::C(a, b, c, d, e, f));
                        pen = end;
                    }
                    "C" => {
                        let (c1, c2, end) = (point(0)?, point(1)?, point(2)?);
                        let ((a, b), (c, d), (e, f)) = (at(c1), at(c2), at(end));
                        current.commands.push(Command::C(a, b, c, d, e, f));
                        pen = end;
                    }
                    "A" => {
                        let (rx, ry) = (value(args[0])? * sx, value(args[1])? * sy);
                        let (start, sweep) = (value(args[2])?, value(args[3])?);
                        pen = arc(pen, rx, ry, start, sweep, &mut |c| {
                            current.commands.push(match c {
                                Command::C(a, b, c, d, e, f) => {
                                    let ((a, b), (c, d), (e, f)) = (
                                        at((f64::from(a), f64::from(b))),
                                        at((f64::from(c), f64::from(d))),
                                        at((f64::from(e), f64::from(f))),
                                    );
                                    Command::C(a, b, c, d, e, f)
                                }
                                other => other,
                            })
                        });
                    }
                    "Z" => current.commands.push(Command::Z),
                    other => return Err(invalid(format!("unknown preset command {other}"))),
                }
            }
        }
    }
    paths.extend(path.map(|p| p.2));
    if paths.iter().flat_map(|p| &p.commands).any(|c| match c {
        Command::M(x, y) | Command::L(x, y) => !x.is_finite() || !y.is_finite(),
        Command::C(a, b, c, d, e, f) => [a, b, c, d, e, f].iter().any(|v| !v.is_finite()),
        Command::Z => false,
    }) {
        return Err(invalid(format!(
            "preset {name} has no finite geometry for this size"
        )));
    }
    Ok(paths)
}

/// OOXML arcs start at the current point; angles are visual angles in 60000ths of a degree.
/// Emits cubic segments in path units and returns the end point.
fn arc(
    pen: (f64, f64),
    rx: f64,
    ry: f64,
    start: f64,
    sweep: f64,
    emit: &mut dyn FnMut(Command),
) -> (f64, f64) {
    if rx <= 0.0 || ry <= 0.0 || sweep == 0.0 {
        return pen;
    }
    // The parametric angle whose ellipse point lies on the visual angle.
    let param = |visual: f64| {
        let v = visual / 60000.0 * PI / 180.0;
        (rx * v.sin()).atan2(ry * v.cos())
    };
    let t0 = param(start);
    let mut t1 = param(start + sweep);
    let full = sweep.abs() >= 21_600_000.0;
    if full {
        t1 = t0 + 2.0 * PI * sweep.signum();
    } else {
        while sweep > 0.0 && t1 <= t0 {
            t1 += 2.0 * PI;
        }
        while sweep < 0.0 && t1 >= t0 {
            t1 -= 2.0 * PI;
        }
    }
    let (cx, cy) = (pen.0 - rx * t0.cos(), pen.1 - ry * t0.sin());
    let segments = ((t1 - t0).abs() / (PI / 2.0)).ceil().max(1.0) as usize;
    let step = (t1 - t0) / segments as f64;
    let k = 4.0 / 3.0 * (step / 4.0).tan();
    let mut t = t0;
    for _ in 0..segments {
        let (s0, c0) = t.sin_cos();
        let (s1, c1) = (t + step).sin_cos();
        let p = |x: f64, y: f64| (x as f32, y as f32);
        let (a, b) = p(cx + rx * (c0 - k * s0), cy + ry * (s0 + k * c0));
        let (c, d) = p(cx + rx * (c1 + k * s1), cy + ry * (s1 - k * c1));
        let (e, f) = p(cx + rx * c1, cy + ry * s1);
        emit(Command::C(a, b, c, d, e, f));
        t += step;
    }
    (cx + rx * t1.cos(), cy + ry * t1.sin())
}

/// The shape guide constants every preset may use.
fn builtins(w: f64, h: f64) -> HashMap<String, f64> {
    let (ss, ls) = (w.min(h), w.max(h));
    let mut v = [
        ("w", w),
        ("h", h),
        ("l", 0.0),
        ("t", 0.0),
        ("r", w),
        ("b", h),
        ("hc", w / 2.0),
        ("vc", h / 2.0),
        ("ss", ss),
        ("ls", ls),
        ("cd2", 10_800_000.0),
        ("cd4", 5_400_000.0),
        ("cd8", 2_700_000.0),
        ("3cd4", 16_200_000.0),
        ("3cd8", 8_100_000.0),
        ("5cd8", 13_500_000.0),
        ("7cd8", 18_900_000.0),
    ]
    .map(|(k, x)| (k.to_owned(), x))
    .into_iter()
    .collect::<HashMap<_, _>>();
    for d in [2, 3, 4, 5, 6, 8, 10, 12, 16, 32] {
        let f = f64::from(d);
        v.insert(format!("wd{d}"), w / f);
        v.insert(format!("hd{d}"), h / f);
        v.insert(format!("ssd{d}"), ss / f);
    }
    v
}
fn operand(s: &str, vars: &HashMap<String, f64>) -> Result<f64> {
    s.parse::<f64>()
        .ok()
        .or_else(|| vars.get(s).copied())
        .ok_or_else(|| invalid(format!("unknown preset guide {s}")))
}
/// One DrawingML guide formula; angles are in 60000ths of a degree.
fn formula(args: &[&str], vars: &HashMap<String, f64>) -> Result<f64> {
    let x = |i: usize| -> Result<f64> {
        args.get(i + 1)
            .ok_or_else(|| invalid("short preset formula"))
            .and_then(|s| operand(s, vars))
    };
    let rad = |a: f64| a / 60000.0 * PI / 180.0;
    let deg = |r: f64| r * 180.0 / PI * 60000.0;
    Ok(
        match *args
            .first()
            .ok_or_else(|| invalid("empty preset formula"))?
        {
            "val" => x(0)?,
            "*/" => x(0)? * x(1)? / x(2)?,
            "+-" => x(0)? + x(1)? - x(2)?,
            "+/" => (x(0)? + x(1)?) / x(2)?,
            "?:" => {
                if x(0)? > 0.0 {
                    x(1)?
                } else {
                    x(2)?
                }
            }
            "abs" => x(0)?.abs(),
            "at2" => deg(x(1)?.atan2(x(0)?)),
            "cat2" => x(0)? * x(2)?.atan2(x(1)?).cos(),
            "sat2" => x(0)? * x(2)?.atan2(x(1)?).sin(),
            "cos" => x(0)? * rad(x(1)?).cos(),
            "sin" => x(0)? * rad(x(1)?).sin(),
            "tan" => x(0)? * rad(x(1)?).tan(),
            "max" => x(0)?.max(x(1)?),
            "min" => x(0)?.min(x(1)?),
            "mod" => (x(0)?.powi(2) + x(1)?.powi(2) + x(2)?.powi(2)).sqrt(),
            "pin" => x(1)?.clamp(x(0)?.min(x(2)?), x(2)?.max(x(0)?)),
            "sqrt" => x(0)?.sqrt(),
            other => return Err(invalid(format!("unknown preset formula {other}"))),
        },
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_preset_evaluates_to_finite_geometry() {
        assert_eq!(names().count(), 187);
        for name in names() {
            for (w, h) in [(200.0, 120.0), (40.0, 300.0), (1.0, 1.0)] {
                let frame = Rect {
                    x: 10.0,
                    y: 20.0,
                    width: w,
                    height: h,
                };
                let paths = geometry(name, frame, &[]).unwrap_or_else(|e| panic!("{name}: {e}"));
                assert!(!paths.is_empty(), "{name}");
            }
        }
    }

    #[test]
    fn right_arrow_matches_its_definition() {
        let frame = Rect {
            x: 0.0,
            y: 0.0,
            width: 200.0,
            height: 100.0,
        };
        let paths = geometry("rightArrow", frame, &[]).unwrap();
        // adj1 50%: shaft half the height; adj2 50% of the short side: head 50px long.
        let points = paths[0]
            .commands
            .iter()
            .filter_map(|c| match c {
                Command::M(x, y) | Command::L(x, y) => Some((*x, *y)),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            points,
            [
                (0.0, 25.0),
                (150.0, 25.0),
                (150.0, 0.0),
                (200.0, 50.0),
                (150.0, 100.0),
                (150.0, 75.0),
                (0.0, 75.0)
            ]
        );
        let ellipse = geometry("ellipse", frame, &[]).unwrap();
        let Command::M(x, y) = ellipse[0].commands[0] else {
            panic!()
        };
        assert_eq!(
            (x, y),
            (0.0, 50.0),
            "ellipse starts at its left middle (arc from 180°)"
        );
    }
}
